let _c2n=null;
function c2Norm(){ if(_c2n) return _c2n; _c2n={}; Object.keys(C2M).forEach(l=>{ _c2n[l]={}; C2CAT.forEach(c=>_c2n[l][c]=C2M[l][c].map(x=>norm(x))); _c2n[l].sub=C2SUB[l].map(x=>norm(x)); }); return _c2n; }
function c2Range(text,lang){
  const N=c2Norm()[lang]||c2Norm().en, tn=norm(text||""), pad=" "+tn+" ", words=tn?tn.split(" "):[];
  const has=p=>pad.includes(" "+p+" ");
  const feats={}; C2CAT.forEach(c=>{ const f=N[c].find(has); feats[c]=f||null; });
  const nCat=C2CAT.filter(c=>feats[c]).length;
  const subs=new Set(N.sub.filter(has)).size;
  const long=words.filter(w=>w.length>=4), ttr=long.length?new Set(long).size/long.length:0;
  const sDisc=Math.min(1,nCat/3), sSub=Math.min(1,subs/2), sLex=long.length<8?0.4:Math.max(0,Math.min(1,(ttr-0.5)/0.3)), sLen=Math.min(1,words.length/35);
  const score=0.45*sDisc+0.2*sSub+0.15*sLex+0.2*sLen;
  return {score,feats,nCat,subs,ttr,words:words.length,parts:{disc:sDisc,sub:sSub,lex:sLex,len:sLen}};
}

