const _convScore5=convScore;
convScore=function(o){ const r=_convScore5(o); if(ATT&&ATT.sc&&ATT.sc._c2&&r.text){ const lang=o.lang||ATT.lang, g=c2Range(r.text,lang), m=c2Range(String(o.d&&o.d.model||"").replace(/…/g,""),lang);
    // C2 range is measured against the model answer of this turn (so short small-talk turns are not penalised)
    g.model=m; const rest=x=>(0.2*x.parts.sub+0.15*x.parts.lex+0.2*x.parts.len)/0.55;
    const discRel=Math.min(1,g.nCat/Math.min(3,Math.max(1,m.nCat))), restRel=Math.min(1,rest(g)/Math.max(0.3,0.9*rest(m)));
    g.rel=Math.max(0,Math.min(1,0.6*discRel+0.4*restRel)); g.modelText=String(o.d&&o.d.model||""); r.c2=g; r.score=Math.max(0,Math.round(r.score*0.6+g.rel*40)); } return r; };

function c2Orig(text,ph){ try{ const re=new RegExp(ph.split(" ").map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("[\\s'’\\-]+"),"i"); const m=String(text||"").match(re); return m?m[0]:ph; }catch(e){ return ph; } }
function c2Panel(res,lang){ const g=res.c2; if(!g) return "";
  const v=Math.round((g.rel!=null?g.rel:g.score)*100), col=v>=80?'var(--ok)':v>=50?'var(--accent2)':'var(--warn)';
  const chips=C2CAT.map(c=>`<span class="kp ${g.feats[c]?"hit":"miss"}" title="${esc(g.feats[c]||"")}">${g.feats[c]?"✓":"✗"} ${t("c2_"+c)}</span>`).join("");
  const miss=C2CAT.filter(c=>!g.feats[c]), mm=g.model&&g.model.feats||{}, inModel=miss.find(c=>mm[c]), tipC=inModel||miss[0], kit=C2KIT[lang]||C2KIT.en;
  const tip=tipC?`<p class="muted" style="margin:4px 0">${t("c2_try",{c:t("c2_"+tipC)})} <i ${tlAttr(lang)}>${esc(kit[tipC].join(" · "))}</i>${inModel?` – ${t("c2_model_uses")} <b ${tlAttr(lang)}>„${esc(c2Orig(g.modelText,mm[inModel]))}“</b>`:""}</p>`:`<p class="muted" style="margin:4px 0">${t("c2_all")}</p>`;
  const extra=[g.subs<2?t("c2_sub"):"",g.words<25?t("c2_len"):""].filter(Boolean).map(x=>`<p class="muted" style="margin:2px 0">${x}</p>`).join("");
  return `<div class="sc" style="margin-top:6px"><span>${t("c2_range")}</span><div class="bar"><i style="width:${v}%;background:${col}"></i></div><b>${v}</b></div><div>${chips}</div>${tip}${extra}`;
}
